INSERT INTO `cl_post_type` (`id`, `uid`, `post_type`, `uri`, `caption`, `content`, `meta_keyword`, `meta_description`, `template`, `banner`, `ordering`, `is_menu`, `is_footer_menu`, `status`, `created_at`, `updated_at`) VALUES
(15, NULL, 'INDUSTRIES', 'industries', NULL, NULL, NULL, NULL, 'posttypeTemplate-industries-list', 'industries-list-banner-JoaR3Ss8bwV6T9fX124zCNyr8bduAf93zCqSOIMx.jpg', 8, '1', 0, '1', '2021-04-16 00:10:31', '2021-04-27 12:54:32'),
(16, NULL, 'SERVICES', 'services', NULL, NULL, NULL, NULL, 'posttypeTemplate-service-list', 'services-list-banner-Sx7fpKKLTEYjzp4YEzWgEyuEFy7yQTfYzHgJwWwX.jpg', 9, '1', 0, '1', '2021-04-16 00:11:05', '2021-04-20 01:40:14'),
(17, NULL, 'ABOUT', 'about', NULL, '<h2><strong>About Us</strong></h2>\r\n<div class=\"row\">\r\n<div class=\"col-md-12\">\r\n<article>\r\n<p>NBSM is a leading Consulting Firm of Nepal offering a wide range of services in the field of Audit, Risk Advisory, Tax Advisory, M&amp;A Advisory and Managed Services for National and Multinational Companies of all sizes.</p>\r\n<p>We enhance value of our clients by focusing on solutions that are innovative, yet practical and that can be implemented. We do this by blending domain expertise with analytical rigor, while maintaining an uncompromising focus on quality - and by hiring and nurturing high quality professionals with a passion for excellence. We are committed to making a difference to our clients and to our people, and we deliver this difference through the integrity of our efforts and by living our core values.</p>\r\n<p><strong>NBSM was founded in 2009. Since its inception, NBSM has been able to&nbsp;position itself as&nbsp;one of the leading and reputed accounting firm in Nepal within a very short span of time. NBSM have the outstanding team of professionals having domain expertise over their areas&nbsp;of Services. NBSM currently have Excellent&nbsp;Team of 100&nbsp;Professionals including 35 Full Time Chartered Accountants with rich experience of providing Auditing Service, Risk Advisory Service, Mergers and Acquisition Advisory Service, Taxation Service, Due Diligence Review Service etc.</strong></p>\r\n<p>NBSM has been a leader in Providing Service to Banking and Financial Institution in Nepal, Insurance Industry in Nepal. More Importantly, NBSM has been providing Services to diversified Industries in Nepal viz. Banking and Financial Institutions, Manufacturing, Trading, Mining, Insurance, Feed and Poultry, Regulatory Boards etc.</p>\r\n</article>\r\n</div>\r\n</div>', NULL, NULL, 'posttypeTemplate-service-list', '', 10, '1', 0, '1', '2021-04-16 00:12:52', '2021-05-10 11:12:16'),
(18, NULL, 'INTERNATIONAL', 'international', 'International', '<p><strong>Moore Global</strong></p>\r\n<p>Moore Global Limited is a global accountancy and consultancy network with its headquarters in London.</p>\r\n<div class=\"page\" title=\"Page 2\">\r\n<div class=\"section\">\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<p>ABOUT MOORE GLOBAL</p>\r\n<p>At Moore, our purpose is to help people thrive &ndash; our clients, our people and the communities they live<br />and work in. We&rsquo;re a global accounting and advisory family of over 30,000 people across more than 260 independent firms and 110 countries, connecting and collaborating to take care of your needs &ndash; local, national and international.</p>\r\n<p>When you work with Moore firms, you&rsquo;ll work with people who care deeply about your success and who have the drive and dedication to deliver results for you and your business. You&rsquo;ll have greater access to senior expertise than with many firms. We&rsquo;ll be here for you whenever you need us &ndash; to help you see through the maze of information, to guide you in your decisions and to make sure you take advantage of every opportunity. To help you thrive in a changing world.</p>\r\n</div>\r\n<div class=\"column\">\r\n<p>WHY WORK WITH US?</p>\r\n<p>Your business is unique, and so is our approach. Our member firms invest time to understand your needs completely, helping you take advantage of every opportunity.</p>\r\n<p>At Moore we do things a little differently:</p>\r\n</div>\r\n</div>\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<ul>\r\n<li>you&rsquo;ll always have a consistent team with a dedicated specialist partner &ndash; so you&rsquo;ll only ever get professional advice to meet your business goals</li>\r\n<li>if your circumstances change, we act fast &ndash; giving you the support and guidance you need to deal with new risks, opportunities, and markets</li>\r\n<li>we&rsquo;re a part of your team, so you have our support whenever you need it &ndash; to make decisions quickly and confidently</li>\r\n<li>if your business needs to expand, our global network across 100 countries can continue to support you as you grow into new markets.</li>\r\n</ul>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p>NBSM is an Independent Firm, in association with Moore Global Limited, Members in principal cities throughout the world.</p>', NULL, NULL, 'page', 'moore-logo-8oWCKSjPD5UH3yZHXVo5MzKj2Na4OlDkwrebLJtW.png', 11, '1', 0, '1', '2021-04-16 00:13:19', '2021-05-25 10:43:20'),
(19, NULL, 'RESOURCES', 'resources', NULL, NULL, NULL, NULL, 'posttypeTemplate-resource-list', '', 12, '1', 0, '1', '2021-04-16 00:15:14', '2021-04-16 06:11:58'),
(20, NULL, 'CONTACT US', 'contact-us', NULL, '<section class=\"bg-primary-dark uk-position-relative uk-flex uk-flex-middle \" data-height-expand=\"\">\r\n<div class=\"uk-width-1-1 uk-position-z-index\">\r\n<div class=\"uk-container uk-container-large uk-position-relative  uk-flex-middle uk-flex\" data-height-expand=\"\">\r\n<div class=\"  uk-width-1-1\">\r\n<p class=\"text-white uk-scrollspy-inview uk-animation-slide-top-small\">To help us address your enquiry, please complete the form below with your details and your reason for contacting us.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</section>\r\n<section class=\"uk-section\">\r\n<div class=\"uk-container uk-container-large\"><form action=\"https://blog.nbsm.com.np/contact-form\" method=\"post\">\r\n<div class=\"uk-grid\">\r\n<div class=\"uk-width-expand@m uk-first-column\">\r\n<div class=\"uk-grid-medium uk-grid\">\r\n<div class=\"uk-width-1-4 uk-first-column\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</form></div>\r\n</section>', NULL, NULL, 'posttypeTemplate-contact-us', '', 13, '1', 0, '1', '2021-04-16 00:15:42', '2021-05-28 04:33:19'),
(21, 'Request For Proposal', 'Request For Proposal', 'request-for-proposal', 'Thank you for your interest in our Firm. Please take a few moments to complete this form. Documents can be uploaded if needed to clarify your request. This mailbox only accepts qualified proposal requests for services. All other inquiries should be directed to our Contact Us page.', NULL, NULL, NULL, 'posttypeTemplate-proposal', '', 14, '0', 0, '1', '2021-05-25 09:56:35', '2021-05-25 13:36:23');
